arguments.command:
python -c 'import csv; from pymatgen.io.vasp import Poscar; from pymatgen.symmetry.analyzer import SpacegroupAnalyzer; rows=list(csv.DictReader(open("/work/cdft_piezo_pool.csv"))); print("ID    Formula         N   V/atom   SG(0.01 A)    PointGroup  SG(0.1 A)");
for r in rows:
 s=Poscar.from_str(r["poscar"]).structure; a=SpacegroupAnalyzer(s,symprec=0.01); b=SpacegroupAnalyzer(s,symprec=0.1); print("{:5s} {:14s} {:3d} {:8.2f} {:12s} {:9s} {:s}".format(r["candidate_id"],r["formula"],len(s),s.volume/len(s),a.get_space_group_symbol(),a.get_point_group_symbol(),b.get_space_group_symbol()))'

